'use strict';
window.PrepJourney=(()=>{
  const model=window.PrepJourneyModel;
  let entryLevel=null,attempts=[],attemptWorkspace=null,loadedWorkspace=null,loading=false,loadError=false,generation=0;
  const icons={book:'M4 4h7a3 3 0 0 1 3 3v14a4 4 0 0 0-4-2H4V4Zm16 0h-6M14 7h6v12h-6',code:'m8 7-5 5 5 5m8-10 5 5-5 5m-3-13-2 16',compass:'m16 8-3 5-5 3 3-5 5-3ZM12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20Z',check:'m5 12 4 4L19 6',layers:'m12 3 10 6-10 6L2 9l10-6Zm-9 11 9 5 9-5M3 18l9 5 9-5',mic:'M12 3a3 3 0 0 0-3 3v6a3 3 0 0 0 6 0V6a3 3 0 0 0-3-3ZM5 10v2a7 7 0 0 0 14 0v-2M12 19v3m-4 0h8',spark:'m12 2 3 7 7 3-7 3-3 7-3-7-7-3 7-3 3-7Z',play:'m9 5 11 7-11 7V5Z',clock:'M12 7v5l3 2M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20Z'};
  const icon=name=>`<svg class="journey-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.book}"/></svg>`;
  const stageIcons={foundations:'book',guided:'code',independent:'compass',depth:'layers',mastery:'mic'};
  const ready=()=>window.PrepPilotUI.workspaceReady?.()===true;
  const savedProfile=()=>state.learningJourney?.version===1?model.profile(state.learningJourney):null;
  const entry=()=>Object.hasOwn(model.levels,route().query.get('level'))?route().query.get('level'):entryLevel||(ready()?savedProfile()?.level:null)||'beginner';
  function itemFor(id,p){const original=baseData.find(item=>item.id===id);if(!original)return null;const variant=window.PREP_LANGUAGES?.[p.language]?.[id]||window.LANGUAGE_CONTENT?.[p.language]?.[id];return original.type==='concept'?window.ConceptAvailability.materialize(original,p.language,variant):{...original,...variant};}
  function stages(p){return model.curriculum(p).map(stage=>({...stage,tasks:stage.tasks.filter(task=>!!itemFor(task.id,p))}));}
  function evidence(){return {reviewed:state.reviewed,reflections:state.journeyReflections,attempts:ready()&&attemptWorkspace===state.pilotWorkspaceKey?attempts:[],catalogue:window.PILOT_CATALOGUE};}
  function taskHref(task,p){const item=itemFor(task.id,p),params=new URLSearchParams({language:p.language,domain:task.kind==='coding'?(item?.domain==='Shared'?'All domains':item?.domain||'Investment Banking'):'All domains',role:task.kind==='rehearsal'?p.role:'all'});if(task.kind==='coding'){params.set('round','coding');params.set('question',task.id);return '#/lab?'+params;}if(task.round)params.set('round',task.round);return '#/lesson/'+task.id+'?'+params;}
  function status(task,p){return model.taskStatus(task,p,evidence());}
  function next(p){return model.recommend(stages(p),p,evidence());}
  function roadPreview(level){const p=model.profile({level}),path=stages(p),active=model.levels[level].stage;return `<div class="journey-map" aria-label="Five-stage learning journey"><div class="journey-map-head"><span>Your path, made clear</span><span class="journey-map-tag">5 stages</span></div><div class="journey-map-route">${path.map(stage=>`<div class="journey-map-step ${stage.id===active?'is-current':''}"><span class="journey-node">${icon(stageIcons[stage.id])}</span><div><strong>${stage.short}</strong><span>${{foundations:'Understand the ideas',guided:'Learn by working through examples',independent:'Solve before revealing the answer',depth:'Reason about the trade-offs',mastery:'Explain, reflect and rehearse'}[stage.id]}</span></div>${stage.id===active?'<small>Your starting point</small>':''}</div>`).join('')}</div><div class="journey-map-footer">${icon('spark')}Small steps. Increasing independence.</div></div>`;}
  function home(){
    const p=ready()?savedProfile():null,recommendation=p?next(p):null,level=entry(),customize=p&&level!==p.level,verified=(window.PILOT_CATALOGUE||[]).filter(item=>item.verification.status==='verified').length;
    return `<div class="journey-home"><section class="journey-hero"><div class="journey-hero-copy"><span class="journey-eyebrow">A CLEAR PATH TO YOUR NEXT INTERVIEW</span><h1>Start where you are.<br><em>Grow into your<br>next role.</em></h1><p>From your first concept to a thoughtful technical conversation. Build the knowledge, practise the skills and learn to explain your decisions with confidence.</p><div class="journey-start-choice"><span>Where are you starting?</span><div class="journey-level-switch" role="group" aria-label="Choose your starting level">${Object.entries(model.levels).map(([id,value])=>`<button data-journey-level="${id}" aria-pressed="${id===level}">${value.name}</button>`).join('')}</div><p id="journey-level-description">${model.levels[level].description}</p></div><div class="journey-hero-actions"><a class="button primary large" href="${p?(customize?'#/learn?setup=1&level='+level:'#/learn'):'#/learn?level='+level}">${icon(p?'play':'compass')}${p?(customize?'Update my starting point':'Continue my journey'):'Build my learning path'}</a><a class="journey-text-link" href="#/concepts">Explore the concepts</a></div><div class="journey-hero-assurance"><span>${icon('check')}Free to start</span><span>${icon('check')}Learn at your own pace</span></div></div><div class="journey-hero-art">${roadPreview(level)}<div class="journey-art-note"><span class="journey-note-mark">a → b</span><p><strong>Understanding comes first.</strong><br>Then practice. Then independence.</p></div></div></section>${p?`<section class="journey-resume"><div class="journey-resume-icon">${icon('play')}</div><div><span class="journey-eyebrow">YOUR NEXT SMALL STEP</span><h2>${esc(recommendation?.task.title||'Revisit a skill and try a fresh challenge')}</h2><p>${esc(recommendation?.stage.short||'Keep practising')} · ${languageConfig[p.language].name} · ${esc(roleConfig.find(role=>role.id===p.role)?.name||'Your role')}</p></div><a class="button primary" href="${recommendation?taskHref(recommendation.task,p):'#/learn'}">${recommendation?.task.kind==='coding'?'Open practice':'Continue learning'}</a></section>`:''}<section class="journey-proof" aria-label="What you can prepare"><div><strong>Learn the why</strong><span>Java & Python concepts</span></div><div><strong>Put it into practice</strong><span>${verified} verified Java exercises</span></div><div><strong>Prepare the conversation</strong><span>All 5 interview rounds</span></div><div><strong>Bring your context</strong><span>6 domains · 7 role paths</span></div></section><section class="journey-section"><div class="journey-section-heading"><div><span class="journey-eyebrow">A LITTLE STRUCTURE GOES A LONG WAY</span><h2>Know what to learn.<br>Know what to do next.</h2></div><p>A collection of questions can be overwhelming. Follow a connected journey that builds on what you already understand.</p></div><div class="journey-method-grid"><article class="journey-method-feature"><span class="journey-feature-icon">${icon('book')}</span><h3>Make the idea click.</h3><p>Short explanations, explorable methods and examples with input and output. Change an input, predict a result and check your understanding.</p><div class="journey-mini-lesson"><div><span>Input</span><code>price = 100.25<br>quantity = 10</code></div><span class="journey-mini-equals">×</span><div><span>The idea</span><strong>A notional is<br>price × quantity.</strong></div></div><a class="journey-text-link" href="#/concepts">Start with a concept</a></article><article class="journey-method-card"><span class="journey-feature-icon">${icon('code')}</span><h3>Get support. Then use less of it.</h3><p>Start with small tasks and progressive hints. Work towards an independent attempt before opening the worked answer.</p><a class="journey-text-link" href="#/lab?round=coding">Try the practice lab</a></article><article class="journey-method-card"><span class="journey-feature-icon">${icon('mic')}</span><h3>Learn to explain your thinking.</h3><p>Practise clarifying a prompt, justifying a decision and discussing risk. Use truthful examples to make the conversation your own.</p><a class="journey-text-link" href="#/rounds">Explore interview rounds</a></article></div></section><section class="journey-round-band"><div><span class="journey-eyebrow">BEYOND GETTING THE CODE RIGHT</span><h2>One journey.<br>Every interview round.</h2><p>Prepare your introduction, your solution and the conversations around them.</p></div><div class="journey-round-list">${roundConfig.map(round=>`<a href="#/round/${round.id}"><span>${round.name}</span><small>${round.label}</small>${icon(round.id==='coding'?'code':'mic')}</a>`).join('')}</div></section><section class="journey-section journey-library"><div class="journey-section-heading"><div><span class="journey-eyebrow">MAKE IT RELEVANT TO YOU</span><h2>Your role. Your language. Your context.</h2></div><p>Foundations come first. Domain scenarios and role-specific questions help you apply them.</p></div><div class="journey-explore-links"><a href="#/domains">${icon('layers')}<span><strong>Explore domains</strong><small>Banking, commerce, AI, cloud and data</small></span></a><a href="#/languages">${icon('code')}<span><strong>Choose a language</strong><small>Java & Python concepts; 4 coding languages</small></span></a><a href="#/roles">${icon('compass')}<span><strong>Find your role</strong><small>Engineering, quality and leadership</small></span></a></div><p class="journey-coverage-note">Automated coding checks currently focus on banking Java. Python, JavaScript and TypeScript have manual practice runners. Every track shows its available material.</p></section><section class="journey-bottom"><span class="journey-eyebrow">YOU DO NOT NEED TO KNOW EVERYTHING TO BEGIN</span><h2>Just take the next useful step.</h2><p>Choose your starting point. We’ll help you find it.</p><a class="button primary large" href="${p?'#/learn?setup=1&level='+level:'#/learn?level='+level}">${icon('compass')}${p?'Adjust my learning path':'Build my learning path'}</a></section></div>`;
  }
  function setup(){const existing=savedProfile(),p=model.profile({language:state.conceptLanguage,domain:currentDomain,role:currentRole,...existing,level:route().query.has('level')?entry():existing?.level||entry()}),session=model.session(p.minutes);return `<div class="journey-setup"><a class="back-link" href="${existing?'#/learn':'#/'}">${existing?'Back to my path':'Back to overview'}</a><div class="journey-page-heading"><span class="journey-eyebrow">LET’S FIND YOUR STARTING POINT</span><h1>A path that meets you<br>where you are.</h1><p>Choose your starting point and focus. You can revisit the basics or jump ahead at any time.</p></div><form id="journey-form" class="journey-onboarding"><fieldset><legend>How does interview preparation feel right now?</legend><div class="journey-level-options">${Object.entries(model.levels).map(([id,value])=>`<label><input type="radio" name="level" value="${id}" ${p.level===id?'checked':''}><span>${icon(id==='beginner'?'book':id==='intermediate'?'code':'compass')}<strong>${value.name}</strong><small>${value.description}</small></span></label>`).join('')}</div></fieldset><div class="journey-form-fields"><label>Concept language<select name="language" id="journey-language">${['java','python'].map(id=>`<option value="${id}" ${p.language===id?'selected':''}>${languageConfig[id].name}</option>`).join('')}</select></label><label>Target role<select name="role" id="journey-role">${roleConfig.map(role=>`<option value="${role.id}" ${p.role===role.id?'selected':''}>${esc(role.name)}</option>`).join('')}</select></label><label>Domain focus<select name="domain" id="journey-domain">${domains.map(domain=>`<option ${p.domain===domain?'selected':''}>${esc(domain)}</option>`).join('')}</select></label><label>Time for a typical session<select name="minutes" id="journey-minutes">${[20,40,60].map(minutes=>`<option value="${minutes}" ${p.minutes===minutes?'selected':''}>About ${minutes} minutes</option>`).join('')}</select></label></div><div class="journey-form-footer"><p>${icon('check')}Changing your path preserves existing code drafts and learning records.</p><button class="button primary large" type="submit">${icon('compass')}${existing?'Update my learning path':'Create my learning path'}</button></div></form>${existing?'<div class="journey-clear-path"><button class="journey-text-button" data-journey-clear>Remove this path</button><span>Lessons, code drafts, reflections and attempts are kept.</span></div>':''}<div class="journey-setup-note"><strong>A starting point, not a test.</strong><p>Your choice changes the recommended starting stage. Earlier stages stay available, and jumping ahead does not mark them complete. Your path and reflections are saved in this browser.</p></div></div>`;}
  function taskCard(task,p){const progress=status(task,p),item=itemFor(task.id,p),spec=p.language==='java'?(window.PILOT_CATALOGUE||[]).find(x=>x.id===task.id):null,manual=task.kind==='coding'&&!spec,key=model.reflectionKey(p,task),reflection=state.journeyReflections?.[key],name=task.kind==='concept'?(item.programming?languageConfig[p.language].name+' concept':'Interview / domain concept'):task.kind==='coding'?(spec?'Java · Automated contract checks':languageConfig[p.language].name+' · Manual practice'):roundFor(task.round).name;return `<article class="journey-task ${progress.done?'is-complete':''}" data-journey-task="${task.id}"><div class="journey-task-icon">${icon(progress.done?'check':task.kind==='concept'?'book':task.kind==='coding'?'code':'mic')}</div><div class="journey-task-main"><div class="journey-task-meta"><span>${esc(name)}</span><span>About ${task.minutes} min</span></div><h3>${esc(task.title)}</h3><p>${task.kind==='concept'?'Read the idea, predict an output and explain it in your own words.':task.kind==='coding'?(task.independent?'Attempt the contract before opening hints or the answer. Check the boundaries and explain your decisions.':'Clarify the example, attempt a solution and use the next hint when you need it.'):'Rehearse aloud using your own experience. State your assumptions and reflect on what you would improve.'}</p><div class="journey-task-actions"><a class="button ${progress.done?'':'primary'}" href="${taskHref(task,p)}">${task.kind==='concept'?'Open lesson':task.kind==='coding'?'Open coding practice':'Open rehearsal question'}</a><span class="journey-task-status" data-source="${progress.source}">${progress.done?icon('check'):''}${esc(progress.label)}</span></div>${task.kind!=='concept'?`<details class="journey-reflection"><summary>${reflection?.note?'My reflection':'Reflect on this step'}</summary><label for="reflection-${task.id}">${manual?'Which cases did you check, and what would you improve?':task.kind==='rehearsal'?'What did you explain well, and what will you change next time?':'Why does your approach work, and which trade-off matters?'}</label><textarea id="reflection-${task.id}" data-journey-note="${task.id}" rows="3" maxlength="3000" placeholder="Write a short reflection in your own words…">${esc(reflection?.note||'')}</textarea><div class="journey-reflection-actions">${progress.source==='reflection'?`<button class="button small" data-journey-record="${task.id}">${progress.done?'Reopen this step':task.kind==='coding'?'Record my self-review':'Record my rehearsal'}</button>`:''}<span data-reflection-status="${task.id}" role="status">${reflection?.note?'Saved in this browser':'Your reflection stays in this browser.'}</span></div>${manual?'<small>Manual practice is self-reviewed. It does not receive an automated contract grade.</small>':''}</details>`:''}</div></article>`;}
  function path(){if(!ready()&&state.learningJourney)return `<div class="journey-loading" role="status">Loading your learning workspace…</div>`;const p=savedProfile();if(!p||route().query.get('setup')==='1')return setup();const path=stages(p),recommended=next(p),requested=route().query.get('stage'),stage=path.find(s=>s.id===requested)||recommended?.stage||path[0],all=path.flatMap(s=>s.tasks),done=all.filter(task=>status(task,p).done),role=roleConfig.find(role=>role.id===p.role),rhythm=model.session(p.minutes);return `<div class="journey-workspace"><header class="journey-workspace-header"><div><span class="journey-eyebrow">YOUR NEXT STEP HAS A PLACE TO LEAD</span><h1>My learning path</h1><p>${languageConfig[p.language].name} · ${esc(role.name)} · ${esc(p.domain)}</p></div><a class="button" href="#/learn?setup=1">Adjust my path</a></header><div class="journey-layout"><aside class="journey-sidebar"><div class="journey-path-summary"><span class="journey-eyebrow">YOUR LEARNING JOURNEY</span><strong>${done.length}<span> / ${all.length} steps recorded</span></strong><progress value="${done.length}" max="${all.length}" aria-label="Learning steps recorded">${done.length} of ${all.length}</progress><p>Reading reviews, contract checks and rehearsals are tracked separately.</p></div><nav aria-label="Learning stages">${path.map(s=>{const count=s.tasks.filter(task=>status(task,p).done).length;return `<a href="#/learn?stage=${s.id}" class="journey-stage-link ${s.id===stage.id?'is-active':''}" ${s.id===stage.id?'aria-current="step"':''}>${icon(stageIcons[s.id])}<span><strong>${s.short}</strong><small>${count} of ${s.tasks.length} steps recorded</small></span>${count===s.tasks.length?icon('check'):''}</a>`;}).join('')}</nav><div class="journey-session"><span>${icon('clock')}A ${p.minutes}-minute session</span><p>${rhythm.learn} min to learn<br>${rhythm.practise} min to practise<br>${rhythm.reflect} min to reflect</p><small>A suggested rhythm. Split longer tasks across sessions.</small></div><a class="journey-text-link" href="#/prepare">Build a 7, 14 or 28-day calendar</a></aside><div class="journey-stage-content"><section class="journey-stage-heading"><span class="journey-stage-label">${icon(stageIcons[stage.id])}${stage.label}</span><h2>${stage.name}</h2><p>${stage.description}</p><details class="journey-outcomes"><summary>What you are working towards</summary><ul>${stage.outcomes.map(text=>`<li>${icon('check')}${esc(text)}</li>`).join('')}</ul></details></section>${recommended&&recommended.stage.id!==stage.id?`<div class="journey-nudge"><p><strong>Your suggested next step:</strong> ${esc(recommended.task.title)}</p><a class="journey-text-link" href="#/learn?stage=${recommended.stage.id}">View suggested stage</a></div>`:''}${stage.id==='guided'||stage.id==='independent'?`<div class="journey-practice-note">${icon('code')}<p>${p.language==='java'?'Banking Java exercises have automated contract checks.':'Python uses the manual practice runner; review its output and your own tests.'} Core coding examples use trades and orders, while your domain focus shapes the later discussion tasks.</p></div>`:''}<div class="journey-task-list">${stage.tasks.map(task=>taskCard(task,p)).join('')}</div><section class="journey-stage-close"><h3>Before you move on</h3><p>Explain one idea without looking at the answer. Give a concrete example, name an edge case and say what you would verify.</p>${path.indexOf(stage)<path.length-1?`<a class="button" href="#/learn?stage=${path[path.indexOf(stage)+1].id}">Explore the next stage</a>`:'<a class="button" href="#/evidence">Review my coding evidence</a>'}</section><p class="journey-evidence-note">${loadError?'Execution history could not be loaded. Learning and self-review remain available. ':''}A recorded step is a review, a rehearsal or a problem-specific check. Coding evidence uses up to 200 recent saved attempts. Recorded steps do not certify expertise or predict an interview outcome. Assistance is browser-recorded and self-reported.</p><button class="journey-text-button" data-journey-refresh>Refresh coding evidence</button></div></div></div>`;}
  function lessonGuide(item){const p=ready()?savedProfile():null;if(!p||item.programming&&item.language!==p.language)return '';const stage=stages(p).find(stage=>stage.tasks.some(task=>task.id===item.id));return stage?`<div class="journey-context"><span>${icon(stageIcons[stage.id])}My learning path <span>/</span> ${stage.short}</span><a href="#/learn?stage=${stage.id}">Back to my path</a></div>`:'';}
  function install(){publicHome=home;const oldLab=labPage;labPage=()=>{const item=labQuestion().item;return (item?lessonGuide(item):'')+oldLab();};}
  async function mount(){const selected=document.querySelector('.journey-stage-link.is-active');if(selected){const nav=selected.parentElement;if(nav.scrollWidth>nav.clientWidth)nav.scrollLeft=Math.max(0,selected.offsetLeft-nav.offsetLeft-(nav.clientWidth-selected.offsetWidth)/2);}const p=savedProfile(),key=state.pilotWorkspaceKey;if(!['learn','home',''].includes(route().path)){loadedWorkspace=null;return;}if(!p||!ready())return;if(attemptWorkspace!==key){attemptWorkspace=key;attempts=[];loadedWorkspace=null;loading=false;loadError=false;generation++;}if(loadedWorkspace===key||loading)return;loadedWorkspace=key;loading=true;const token=++generation;try{const records=await window.PrepPilotUI.learningAttempts();if(token!==generation||key!==state.pilotWorkspaceKey)return;attempts=records;loadError=false;}catch{if(key===state.pilotWorkspaceKey){attempts=[];loadError=true;}}finally{if(token===generation){loading=false;if(['learn','home'].includes(route().path))render();}}}
  function currentTask(id){const p=savedProfile();if(!p||!ready())return null;const task=stages(p).flatMap(stage=>stage.tasks).find(task=>task.id===id);return task?{p,task,key:model.reflectionKey(p,task)}:null;}
  document.addEventListener('submit',event=>{if(event.target.id!=='journey-form')return;event.preventDefault();if(!ready()){toast('Your learning workspace is loading. Try again in a moment.');return;}const form=new FormData(event.target),p=model.profile(Object.fromEntries(form));state.learningJourney={...p,createdAt:state.learningJourney?.createdAt||new Date().toISOString(),updatedAt:new Date().toISOString()};state.conceptLanguage=p.language;state.language=p.language;currentLanguage=p.language;currentDomain=p.domain;state.domain=p.domain;currentRole=p.role;state.role=p.role;category='All';refreshLanguageContent();persist();loadedWorkspace=null;go('learn?stage='+model.levels[p.level].stage);render();});
  document.addEventListener('click',event=>{const level=event.target.closest('[data-journey-level]');if(level){entryLevel=level.dataset.journeyLevel;render();document.querySelector(`[data-journey-level="${entryLevel}"]`)?.focus({preventScroll:true});}const record=event.target.closest('[data-journey-record]');if(record){const selected=currentTask(record.dataset.journeyRecord);if(!selected)return;state.journeyReflections??={};const reflection=state.journeyReflections[selected.key]??={note:'',reviewed:false};if(reflection.note.trim().length<20){document.querySelector(`[data-reflection-status="${selected.task.id}"]`).textContent='Write at least 20 characters about what you practised.';document.getElementById('reflection-'+selected.task.id)?.focus();return;}reflection.reviewed=!reflection.reviewed;reflection.updatedAt=new Date().toISOString();persist();render();toast(reflection.reviewed?'Self-review recorded. Return to it whenever you need.':'Step reopened for another practice.');}if(event.target.closest('[data-journey-refresh]')){loadedWorkspace=null;render();}if(event.target.closest('[data-journey-clear]')&&ready()){delete state.learningJourney;entryLevel='beginner';loadedWorkspace=null;persist();go('learn');render();toast('Path removed. Your learning records and code drafts are kept.');}});
  document.addEventListener('input',event=>{const id=event.target.dataset.journeyNote;if(!id)return;const selected=currentTask(id);if(!selected)return;state.journeyReflections??={};const old=state.journeyReflections[selected.key]||{};state.journeyReflections[selected.key]={...old,note:event.target.value.slice(0,3000),reviewed:false,updatedAt:new Date().toISOString()};const saved=persist();document.querySelector(`[data-reflection-status="${id}"]`).textContent=saved?(status(selected.task,selected.p).source==='checks'?'Reflection saved in this browser.':'Draft saved in this browser. Record your self-review when ready.'):'Browser storage unavailable. Copy your reflection before leaving.';});
  document.addEventListener('keydown',event=>{if(event.key==='Escape')document.querySelectorAll('.journey-explore[open]').forEach(details=>details.open=false);});
  return {install,mount,home,path,lessonGuide,stages,taskHref,views:{learn:path}};
})();
